<?php use Marketplace\Bus\Repository\BlackBoxRepository; ?>
<div class="table-scroll"><table><caption class="sr-only"><?= e($title) ?></caption>
<?php if ($matrixType === 'cobertura'): ?><thead><tr><th>Métrica</th><th>Total</th><th>Cubiertos</th><th>Porcentaje</th><th>Herramienta Utilizada</th></tr></thead><tbody><?php foreach (Marketplace\Bus\Repository\CoverageMetrics::METRICS as $metric => $label): $row = $data['metricas'][$metric]; ?><tr><th scope="row"><?= e($label) ?></th><td><?= e((string) $row['total']) ?></td><td><?= e((string) $row['cubiertos']) ?></td><td><?= number_format((float) $row['porcentaje'], 2, '.', '') ?> %</td><td class="wrap-cell"><?= e($row['herramienta']) ?></td></tr><?php endforeach; ?></tbody>
<?php elseif ($matrixType !== 'decision'): ?><thead><tr><?php foreach (BlackBoxRepository::FIELDS[$matrixType] as $label): ?><th><?= e($label) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach ($data['filas'] as $row): ?><tr><?php foreach (BlackBoxRepository::FIELDS[$matrixType] as $field => $label): ?><td class="wrap-cell"><?= nl2br(e($row[$field])) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody>
<?php else: ?><thead><tr><th>Condición / Acción</th><?php foreach ($data['reglas'] as $rule): ?><th><?= e($rule) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach (['condiciones' => 'Condición', 'acciones' => 'Acción'] as $kind => $label): ?><?php foreach ($data[$kind] as $element): ?><tr><td class="wrap-cell"><?= e($label . ': ' . $element['texto']) ?></td><?php foreach ($element['valores'] as $value): ?><td><?= $value === '-' ? '–' : e($value) ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php endforeach; ?></tbody><?php endif; ?>
</table></div>
